import sys
from datetime import datetime


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def compute_block_rate(start_minutes):
    start_time = datetime.fromtimestamp(start_minutes * 60)
    hour = start_time.hour
    if 8 <= hour < 20:
        return 2.50
    return 1.00


def compute_period_blocks(duration_minutes):
    blocks = (duration_minutes + 59) // 60
    periods = (blocks + 23) // 24
    return periods


def compute_period_fee(blocks, start_minutes):
    fee = 0.0
    for p in range(compute_period_blocks(blocks)):
        start_block_minutes = start_minutes + p * 60 * 24
        for b in range(24):
            block_start_minutes = start_block_minutes + b * 60
            fee += compute_block_rate(block_start_minutes)
            if fee >= 18.0:
                break
        if fee >= 18.0:
            break
    return min(fee, 18.0)


def calculate_fee(entry_time_str, exit_time_str):
    entry = datetime.strptime(entry_time_str, "%Y-%m-%d %H:%M")
    exit_ = datetime.strptime(exit_time_str, "%Y-%m-%d %H:%M")
    if exit_ <= entry:
        return None, None

    duration_minutes = (exit_.timestamp() - entry.timestamp()) // 60

    if duration_minutes <= 30:
        fee = 0.0
    else:
        fee = compute_period_fee(duration_minutes, entry.timestamp() // 60)

    hours = duration_minutes // 60
    minutes = duration_minutes % 60
    return hours, minutes, fee


def main():
    totals = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 5:
            print(f"{parts[0]} invalid")
            continue
        plate, entry_date_time, _, exit_date_time = parts
        entry_time_str, _ = entry_date_time.split()
        _, exit_time_str = exit_date_time.split()

        hours, minutes, fee = calculate_fee(entry_time_str, exit_time_str)
        if hours is None:
            print(f"{plate} invalid")
            continue

        print(f"{plate} {hours}:{minutes:02d} {fee:.2f}")
        totals[plate] = totals.get(plate, 0.0) + fee

    print("---")

    valid_plates = {k: v for k, v in totals.items() if v > 0.0}
    sorted_plates = sorted(
        valid_plates.items(),
        key=lambda item: (-item[1], item[0]),
    )

    for plate, total_fee in sorted_plates:
        print(f"{plate} {len([p for p in totals if p == plate])} {total_fee:.2f}")


if __name__ == "__main__":
    main()
